*{box-sizing:border-box} :root{--ink:#252c2a;--muted:#8b918c;--paper:#f6f3ed;--white:#fffefa;--line:#e7e2d9;--coral:#d27866;--sage:#78917f;--gold:#c69d59} html,body{margin:0;min-height:100%;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif}body{min-width:320px}.app-shell{max-width:1512px;margin:0 auto;padding:0 56px}.topbar{height:82px;border-bottom:1px solid #e8e3dc;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink);font-family:'Playfair Display',serif;font-size:21px;font-weight:600;letter-spacing:-.7px}.brand-light{font-weight:500;color:#858982}.brand-mark{height:35px;width:35px;border-radius:12px;background:#d27c69;color:#fff;display:grid;place-items:center;font-family:'Playfair Display',serif;font-size:22px;position:relative}.brand-mark span{position:absolute;color:#f5d6a5;font:10px sans-serif;right:4px;top:3px}.top-center{font-size:10px;font-weight:700;letter-spacing:1.55px;color:#444b47}.live-dot{height:7px;width:7px;background:#83a78b;display:inline-block;border-radius:50%;margin-right:7px;box-shadow:0 0 0 3px #83a78b24}.top-separator{margin:0 9px;color:#c1bdb5}.top-muted{color:#999c96;font-weight:500}.top-actions{display:flex;gap:12px;align-items:center}.icon-button,.help-button{border:1px solid var(--line);background:transparent;color:var(--ink);height:36px;border-radius:8px}.icon-button{width:38px;font-size:18px}.help-button{padding:0 14px;font-size:9px;font-weight:700;letter-spacing:1px}.help-button span{color:var(--coral);margin-left:7px;font-size:13px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 336px;gap:36px;padding:31px 0 32px}.stage-column{min-width:0}.stage-heading{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:19px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.6px;color:#9b8d7e;margin-bottom:7px}.stage-heading h1,.panel-title h2,.help-modal h2{font-family:'Playfair Display',serif;margin:0;letter-spacing:-.7px;font-weight:500}.stage-heading h1{font-size:34px}.stage-heading-right{display:flex;align-items:center;gap:16px;padding-bottom:4px}.session-pill{font-size:9px;color:#7e887f;letter-spacing:.8px;font-weight:700}.session-pill .live-dot{height:6px;width:6px}.reset-button{border:0;border-left:1px solid #ddd7ce;background:none;padding:0 0 0 16px;color:#666c65;font:500 11px 'DM Sans';cursor:pointer}.reset-button:first-letter{font-size:16px}.stage-frame{background:#242a29;border-radius:13px;padding:0 0 0;overflow:hidden;box-shadow:0 14px 34px #3b342715;position:relative}.stage-topline{height:39px;display:flex;justify-content:space-between;align-items:center;padding:0 18px;color:#b9c1bb;font-size:8px;letter-spacing:1.3px;font-weight:700}.tiny-star{color:#d39a78;font-style:normal;margin-right:6px}.stage-topline>span:last-child{font-size:8px;color:#929b94}.stage-topline b{font-size:8px;color:#e3a18a;margin-left:6px}.viewport{height:min(58vw,565px);min-height:390px;position:relative;overflow:hidden;cursor:crosshair;background:radial-gradient(ellipse at 50% 40%,#4c5650 0%,#343d39 48%,#242a29 100%);touch-action:none}.viewport canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.scene-tag{position:absolute;top:17px;left:18px;display:flex;align-items:center;gap:9px;background:#202624bd;border:1px solid #ffffff17;border-radius:9px;padding:8px 11px;color:#f5f2ea;backdrop-filter:blur(8px);pointer-events:none}.tag-avatar{height:28px;width:28px;border-radius:50%;display:grid;place-items:center;background:#bd856c;font:13px 'Playfair Display';color:white}.scene-tag b{display:block;font-size:10px;font-weight:600}.scene-tag small{display:block;font-size:8px;color:#b6beb7;margin-top:3px}.scene-hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;background:#202624bd;border:1px solid #ffffff1a;border-radius:20px;padding:9px 14px;color:#e1e3dc;font-size:10px;pointer-events:none;transition:opacity .4s}.scene-hint span{color:#e0b281;margin-right:5px}.crosshair{display:none;position:absolute;left:50%;top:50%;width:30px;height:30px;border:1px solid #fff9;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}.crosshair:before,.crosshair:after{content:'';position:absolute;background:#fff9}.crosshair:before{width:1px;height:7px;left:14px;top:-5px}.crosshair:after{width:7px;height:1px;left:-5px;top:14px}.cut-toast{position:absolute;display:none;background:#d27c69;color:white;font-size:9px;letter-spacing:1px;font-weight:700;padding:7px 10px;border-radius:5px;pointer-events:none}.loading-card{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#d5d9d2;font-size:11px;letter-spacing:.4px;background:#303735;z-index:5;transition:opacity .4s}.loading-card.hidden{opacity:0;pointer-events:none}.loading-spinner{width:22px;height:22px;border:2px solid #ffffff32;border-top-color:#d3977e;border-radius:50%;animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.stage-footer{height:47px;display:flex;align-items:center;justify-content:space-between;padding:0 17px;color:#adb4ae;font-size:9px}.stage-footer kbd{font-family:inherit;color:#d8ddd5;border:1px solid #ffffff34;border-radius:3px;padding:2px 4px;font-size:7px;letter-spacing:.4px}.wind-button{border:1px solid #ffffff27;background:#ffffff0b;border-radius:5px;color:#e6e9e2;height:27px;padding:0 9px;font:500 9px 'DM Sans';cursor:pointer}.wind-button span{font-size:13px;color:#d1a878;margin-right:5px}.wind-button i{font-style:normal;font-size:7px;color:#9fa69f;margin-left:6px;letter-spacing:.8px}.wind-button.active{border-color:#d3977e88;background:#d3977e25}.wind-button.active i{color:#e6aa8d}.bottom-stats{display:grid;grid-template-columns:1fr 1fr 1.65fr;gap:11px;margin-top:13px}.stat-card{height:73px;background:#fffefa;border:1px solid #ebe6de;border-radius:8px;display:flex;align-items:center;padding:0 12px;gap:10px;min-width:0}.stat-icon{width:31px;height:31px;border-radius:9px;display:grid;place-items:center;font-size:15px;flex:none}.stat-icon.coral{background:#f8eae5;color:#ce806c}.stat-icon.sage{background:#e8eee8;color:#738e7b}.stat-icon.gold{background:#f6efdf;color:#bc9556}.stat-copy{min-width:0}.stat-copy small{display:block;color:#9b9d96;font-size:7px;font-weight:700;letter-spacing:1px;margin-bottom:6px}.stat-copy b{font-size:15px;font-weight:600;white-space:nowrap}.stat-copy em{font-size:9px;color:#93968f;font-style:normal;font-weight:500}.goal-card{position:relative}.goal-card .stat-copy b{font-family:'Playfair Display',serif;font-size:13px;font-weight:500}.goal-status{margin-left:auto;color:#93a08e;font-size:7px;letter-spacing:.7px;font-weight:700;white-space:nowrap}.tool-panel{background:#fffefa;border:1px solid #ebe6de;border-radius:11px;padding:23px 20px 14px;display:flex;flex-direction:column;min-height:100%}.panel-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:17px}.panel-title h2{font-size:22px}.tool-count{font:500 10px 'Playfair Display';color:#b4a999;border:1px solid #ece7de;border-radius:50%;width:27px;height:27px;display:grid;place-items:center}.tool-list{display:flex;flex-direction:column;gap:8px}.tool-card{height:66px;background:#fffefa;border:1px solid #ece8e1;border-radius:8px;display:flex;align-items:center;text-align:left;padding:0 10px;gap:10px;cursor:pointer;color:var(--ink);transition:all .16s}.tool-card:hover{border-color:#d9b8a8;transform:translateY(-1px)}.tool-card.selected{background:#fbf4ef;border-color:#dcaa98;box-shadow:inset 3px 0 #d27c69}.tool-illustration{width:40px;height:40px;border-radius:8px;display:grid;place-items:center;background:#f6f2ec;flex:none}.tool-illustration svg{width:33px;height:33px;fill:none;stroke:#59615b;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.scissors-illustration svg{stroke:#c97865}.thinning-illustration svg{stroke:#a78a66}.clipper-illustration svg{stroke:#6f8b79}.comb-illustration svg{stroke:#728b82}.tool-info{flex:1;min-width:0}.tool-info b{display:block;font-size:10px;font-weight:700;margin-bottom:4px}.tool-info small{display:block;color:#989b95;font-size:8px}.tool-key{border:1px solid #e9e5dd;border-radius:4px;color:#a6a69e;padding:3px 5px;font-size:8px}.tool-detail{height:50px;background:#f7f5f0;border-radius:7px;margin-top:12px;display:flex;align-items:center;gap:9px;padding:0 10px}.detail-icon{height:25px;width:25px;border-radius:50%;background:#f0dfd7;color:#c47966;display:grid;place-items:center;font-size:12px}.tool-detail b{font-size:9px;display:block;margin-bottom:3px}.tool-detail small{font-size:8px;color:#969a93}.divider{height:1px;background:#eeeae3;margin:18px 0 14px}.section-label{display:flex;justify-content:space-between;font-size:8px;font-weight:700;letter-spacing:1px;color:#8f9189}.goal-count{font-weight:500;color:#9a9d94;letter-spacing:0}.progress-track{height:4px;background:#eeebe4;border-radius:4px;margin-top:10px;overflow:hidden}.progress-track span{height:100%;width:0;display:block;background:linear-gradient(90deg,#d27c69,#d5a77e);border-radius:4px;transition:width .3s}.goal-note{color:#8e938c;font-size:9px;line-height:1.6;margin:11px 0 16px}.mini-guide{display:flex;align-items:center;gap:9px;background:#f2f5ef;border:1px solid #e6ece3;border-radius:7px;padding:10px 9px}.guide-icon{height:25px;width:25px;border-radius:7px;background:#e4ece1;color:#80947f;display:grid;place-items:center;font-size:14px;flex:none}.mini-guide b{display:block;font-size:8px;margin-bottom:4px}.mini-guide small{display:block;color:#90978e;font-size:7px;line-height:1.45}.mini-guide button{margin-left:auto;flex:none;border:0;border-radius:5px;background:#fffefa;color:#819282;width:24px;height:24px;cursor:pointer}.panel-bottom{margin-top:auto;padding-top:15px;color:#a5a69e;font-size:7px;letter-spacing:.2px}.saved-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:#98b298;margin-right:5px}.page-footer{border-top:1px solid #e8e3dc;height:42px;display:flex;justify-content:space-between;align-items:center;color:#aaa99f;font-size:7px;font-weight:700;letter-spacing:1px}.page-footer i{font-style:normal;color:#d27c69;margin:0 4px}.page-footer b{color:#d27c69;font-size:12px;margin-left:4px}.modal-backdrop{position:fixed;inset:0;background:#19201dcc;display:none;align-items:center;justify-content:center;z-index:20;padding:20px}.modal-backdrop.open{display:flex}.help-modal{position:relative;background:#fffefa;border-radius:14px;padding:36px;width:min(480px,100%);box-shadow:0 24px 80px #10161455}.help-modal h2{font-size:32px;margin-bottom:12px}.help-modal>p{font-size:12px;line-height:1.7;color:#818780;margin:0 0 22px}.modal-close{position:absolute;right:17px;top:14px;border:0;background:none;color:#858a83;font-size:24px;cursor:pointer}.help-steps{display:grid;gap:9px}.help-steps>div{display:grid;grid-template-columns:27px 1fr;column-gap:9px;padding:12px;border:1px solid #ece8e0;border-radius:7px}.help-steps>div>span{grid-row:span 2;color:#ca806a;font-size:9px;font-weight:700}.help-steps b{font-size:10px}.help-steps small{font-size:9px;color:#969991;margin-top:4px;line-height:1.5}.modal-done{width:100%;height:42px;margin-top:20px;border:0;border-radius:6px;background:#d27c69;color:#fff;font-size:9px;font-weight:700;letter-spacing:1px;cursor:pointer}.modal-done span{margin-left:12px;font-size:14px}
@media(max-width:1100px){.app-shell{padding:0 28px}.workspace{grid-template-columns:minmax(0,1fr) 300px;gap:22px}.viewport{height:min(62vw,520px)}.tool-panel{padding:20px 15px 13px}.bottom-stats{grid-template-columns:1fr 1fr}.goal-card{grid-column:span 2}.stat-card{height:66px}}
@media(max-width:800px){.app-shell{padding:0 16px}.topbar{height:65px}.top-center{display:none}.workspace{display:flex;flex-direction:column;padding:23px 0;gap:17px}.stage-heading h1{font-size:29px}.viewport{height:min(102vw,540px);min-height:350px}.tool-panel{display:grid;grid-template-columns:1fr 1fr;gap:0 18px;padding:18px}.panel-title{grid-column:span 2}.tool-list{grid-column:span 2;display:grid;grid-template-columns:1fr 1fr}.tool-card{height:62px;padding:0 7px;gap:6px}.tool-illustration{width:34px;height:34px}.tool-illustration svg{width:29px;height:29px}.tool-info b{font-size:9px}.tool-info small{font-size:7px}.tool-detail{grid-column:span 2}.divider{grid-column:span 2;margin:13px 0}.section-label,.progress-track,.goal-note,.mini-guide,.panel-bottom{grid-column:span 2}.panel-bottom{padding-top:12px}.stage-footer{padding:0 10px;font-size:8px}.stage-footer kbd{font-size:6px}.page-footer{font-size:6px}.goal-card .stat-copy b{font-size:12px}}
@media(max-width:460px){.app-shell{padding:0 11px}.brand{font-size:18px}.top-actions{gap:7px}.help-button{padding:0 9px;font-size:8px}.stage-heading h1{font-size:25px}.stage-heading-right{gap:8px}.session-pill{font-size:7px}.reset-button{padding-left:9px;font-size:10px}.viewport{min-height:350px}.scene-hint{font-size:8px;padding:8px 10px}.stage-footer>span{max-width:210px;line-height:1.8}.bottom-stats{gap:6px}.stat-card{padding:0 7px;gap:7px}.stat-icon{width:26px;height:26px}.stat-copy small{font-size:6px}.stat-copy b{font-size:13px}.goal-status{font-size:6px}.tool-panel{padding:15px 11px}.tool-card{height:59px}.tool-illustration{width:30px;height:30px}.tool-info b{font-size:8px}.tool-info small{font-size:6px}.tool-key{padding:2px 4px}.page-footer span:last-child{display:none}}

import * as THREE from 'three';

const viewport = document.getElementById('viewport');
const scene = new THREE.Scene();
scene.background = new THREE.Color('#303936');
scene.fog = new THREE.Fog('#303936', 8, 18);
const camera = new THREE.PerspectiveCamera(33, 1, .1, 50);
const renderer = new THREE.WebGLRenderer({antialias:true, alpha:false, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.16;
viewport.prepend(renderer.domElement);

const root = new THREE.Group(); scene.add(root);
const hemi = new THREE.HemisphereLight(0xdce9e3, 0x594a44, 2.0); scene.add(hemi);
const keyLight = new THREE.DirectionalLight(0xffe6cc, 3.2); keyLight.position.set(-3.8,5.8,5.5); scene.add(keyLight);
const rimLight = new THREE.DirectionalLight(0x9dbfc0, 3.4); rimLight.position.set(3.5,4.0,-3); scene.add(rimLight);
const softLight = new THREE.PointLight(0xffc7a8, 70, 8, 2); softLight.position.set(2.6,2.4,3.8); scene.add(softLight);

const mat = (color, roughness=.6, metalness=0) => new THREE.MeshStandardMaterial({color,roughness,metalness});
const skin = new THREE.MeshStandardMaterial({color:'#d9a98e',roughness:.72});
const skinLight = new THREE.MeshStandardMaterial({color:'#e4b79d',roughness:.64});
const dark = mat('#302825',.35);
const browMat = mat('#644337',.82);
const irisMat = mat('#6e837c',.35);
const lipMat = mat('#a96d68',.62);
function ellipsoid(name, colorMat, pos, scale, parent=root, geo=new THREE.SphereGeometry(1,32,24)){
  const mesh = new THREE.Mesh(geo,colorMat); mesh.name=name; mesh.position.set(...pos); mesh.scale.set(...scale); parent.add(mesh); return mesh;
}
function cylinder(name, colorMat, radiusTop,radiusBottom,height,pos,segments=32){const m=new THREE.Mesh(new THREE.CylinderGeometry(radiusTop,radiusBottom,height,segments),colorMat);m.name=name;m.position.set(...pos);root.add(m);return m;}

// Salon bust, softly lit backdrop and an understated brass chair halo.
const bodyMat = mat('#bd8d78',.72);
ellipsoid('shoulders',bodyMat,[0,.02,-.05],[1.16,.52,.56]);
ellipsoid('neck',skin,[0,.73,0],[.38,.75,.39]);
ellipsoid('neck shadow',mat('#bc8c75',.8),[0,.73,-.025],[.385,.73,.365]);
// Restore a gently highlighted front of the neck above the chest.
ellipsoid('neck front',skin,[0,.78,.08],[.355,.68,.34]);
const headCenterY=1.78, headRx=.76, headRy=1.05, headRz=.61;
ellipsoid('head',skin,[0,headCenterY,0],[headRx,headRy,headRz],root,new THREE.SphereGeometry(1,64,48));
// Jaw and cheek volumes add a more human profile without hiding the face.
ellipsoid('left cheek',skinLight,[-.39,1.42,.34],[.32,.34,.25]);
ellipsoid('right cheek',skinLight,[.39,1.42,.34],[.32,.34,.25]);
ellipsoid('chin',skinLight,[0,1.02,.37],[.39,.27,.25]);
for(const side of [-1,1]){
  ellipsoid('ear',skinLight,[side*.76,1.55,.015],[.17,.27,.15]);
  ellipsoid('ear inset',mat('#bb806f',.82),[side*.84,1.55,.12],[.075,.15,.035]);
  ellipsoid('eye white',mat('#f2e7dc',.32),[side*.285,1.78,.535],[.14,.085,.065]);
  ellipsoid('iris',irisMat,[side*.285,1.775,.59],[.051,.055,.025]);
  ellipsoid('pupil',dark,[side*.285,1.775,.611],[.023,.031,.013]);
  ellipsoid('eye glint',mat('#fff8e9',.18),[side*.299,1.795,.624],[.012,.013,.008]);
  const brow=ellipsoid('brow',browMat,[side*.285,1.925,.545],[.17,.036,.04]);brow.rotation.z=side*-.08;
  ellipsoid('earring',mat('#d6b876',.28,.6),[side*.82,1.28,.15],[.035,.10,.035]);
}
// Soft nose bridge and nostril shadow.
ellipsoid('nose bridge',skinLight,[0,1.58,.565],[.105,.25,.12]);
ellipsoid('nose tip',skinLight,[0,1.43,.625],[.13,.09,.10]);
for(const side of [-1,1]) ellipsoid('nostril',mat('#a97869',.8),[side*.075,1.4,.69],[.035,.019,.016]);
ellipsoid('upper lip',lipMat,[0,1.245,.575],[.17,.042,.055]);
ellipsoid('lower lip',mat('#bf8179',.62),[0,1.205,.578],[.15,.038,.05]);
ellipsoid('lip line',mat('#80534e',.9),[0,1.226,.62],[.135,.009,.009]);
// Collar and bust detail.
const collar=ellipsoid('collar',mat('#e7ded0',.85),[0,.56,.05],[.45,.16,.37]);
const base=cylinder('chair pedestal',mat('#333a36',.35,.35),.52,.62,.34,[0,-.52,-.04]);
const baseTrim=cylinder('pedestal trim',mat('#c4a16d',.25,.7),.64,.58,.045,[0,-.32,-.04]);
// Ring backdrop gives a warm salon mirror silhouette.
const halo=new THREE.Mesh(new THREE.TorusGeometry(1.63,.012,8,128),new THREE.MeshStandardMaterial({color:'#bd9c71',metalness:.7,roughness:.3,emissive:'#5c4931',emissiveIntensity:.3}));halo.position.set(0,1.65,-1.0);root.add(halo);
const floor=new THREE.Mesh(new THREE.CircleGeometry(5,64),mat('#3a423e',.85));floor.rotation.x=-Math.PI/2;floor.position.y=-.72;root.add(floor);

// A layered field of individually simulated fibers. Each follicle carries a small Verlet chain.
const STRAND_COUNT=480, NODES=7, RADIAL=3, VERTS=NODES*RADIAL;
const strands=[];
const positions=new Float32Array(STRAND_COUNT*VERTS*3), colors=new Float32Array(positions.length), indices=[];
const golden=new THREE.Color('#81502f'), chestnut=new THREE.Color('#43291f'), highlight=new THREE.Color('#bd8250');
const strandMaterial=new THREE.MeshStandardMaterial({vertexColors:true,roughness:.38,metalness:.13,side:THREE.DoubleSide});
for(let s=0;s<STRAND_COUNT;s++){
  const row=Math.floor(s/24), col=s%24;
  const lat=.16 + row/19*1.25 + (Math.random()-.5)*.045;
  const theta=(col/24)*Math.PI*2 + (row%2)*.12 + (Math.random()-.5)*.045;
  const length=(.82+Math.random()*.42)*(1.02+Math.sin(theta*2)*.12);
  const layer=(s%3)*.018;
  const rootPos=guidePoint(lat,theta,0,length,layer);
  const pts=[], prev=[];
  for(let n=0;n<NODES;n++){const p=guidePoint(lat,theta,n/(NODES-1),length,layer);pts.push(p.clone());prev.push(p.clone());}
  const shade=Math.random();
  const c=chestnut.clone().lerp(golden,shade*.42);
  if(Math.random()<.13)c.lerp(highlight,.24+Math.random()*.16);
  strands.push({lat,theta,length,layer,pts,prev,active:NODES,cut:false,color:c,phase:Math.random()*Math.PI*2,weight:.7+Math.random()*.65});
  const baseVertex=s*VERTS;
  for(let n=0;n<NODES;n++) for(let r=0;r<RADIAL;r++){
    const v=(baseVertex+n*RADIAL+r)*3;
    colors[v]=c.r;colors[v+1]=c.g;colors[v+2]=c.b;
  }
  for(let n=0;n<NODES-1;n++)for(let r=0;r<RADIAL;r++){
    const a=baseVertex+n*RADIAL+r,b=baseVertex+n*RADIAL+(r+1)%RADIAL,c1=baseVertex+(n+1)*RADIAL+r,d=baseVertex+(n+1)*RADIAL+(r+1)%RADIAL;
    indices.push(a,c1,b,b,c1,d);
  }
}
function guidePoint(lat,theta,t,length,layer=0){
  // Hair follows the skull and falls down the temples and nape, then drapes free.
  const a=lat+t*(1.15+length*.16);
  const sin=Math.sin(a), cos=Math.cos(a);
  const flow=t*t;
  const x=(headRx+.035+layer)*sin*Math.cos(theta) + Math.sign(Math.cos(theta)||1)*flow*.09;
  const z=(headRz+.045+layer)*sin*Math.sin(theta) + .018*Math.sin(theta*2+t*3);
  const y=headCenterY+(headRy+.055+layer)*cos - flow*.11;
  return new THREE.Vector3(x,y,z);
}
const hairGeometry=new THREE.BufferGeometry();hairGeometry.setIndex(indices);hairGeometry.setAttribute('position',new THREE.BufferAttribute(positions,3).setUsage(THREE.DynamicDrawUsage));hairGeometry.setAttribute('color',new THREE.BufferAttribute(colors,3));
const hairMesh=new THREE.Mesh(hairGeometry,strandMaterial);hairMesh.frustumCulled=false;root.add(hairMesh);
// Smooth dark underlayer makes the fibers feel dense rather than like isolated wires.
const hairCap=ellipsoid('underlayer',mat('#472d24',.48),[0,headCenterY+.04,-.015],[.8,1.09,.645],root,new THREE.SphereGeometry(1,48,36));

function updateHairGeometry(){
  for(let s=0;s<STRAND_COUNT;s++){
    const strand=strands[s], base=s*VERTS;
    for(let n=0;n<NODES;n++){
      const p=strand.pts[Math.min(n,strand.active-1)] || strand.pts[0];
      const tangent=(n===0?strand.pts[1].clone().sub(p):p.clone().sub(strand.pts[Math.max(0,n-1)])).normalize();
      const axis=new THREE.Vector3(0,0,1);if(Math.abs(tangent.dot(axis))>.92)axis.set(0,1,0);
      const side=new THREE.Vector3().crossVectors(tangent,axis).normalize();
