const collisionCell=.075;
function collideStrands(){
  const grid=new Map();
  for(let s=0;s<strands.length;s++){
    const st=strands[s];
    for(let n=2;n<st.active;n++){
      const p=st.pts[n],key=`${Math.floor(p.x/collisionCell)},${Math.floor(p.y/collisionCell)},${Math.floor(p.z/collisionCell)}`;
      if(!grid.has(key))grid.set(key,[]);grid.get(key).push({s,n,p});
    }
  }
  const dirs=[-1,0,1];
  for(const bucket of grid.values())for(const a of bucket){
    const cx=Math.floor(a.p.x/collisionCell),cy=Math.floor(a.p.y/collisionCell),cz=Math.floor(a.p.z/collisionCell);
    for(const dx of dirs)for(const dy of dirs)for(const dz of dirs){
      const other=grid.get(`${cx+dx},${cy+dy},${cz+dz}`);if(!other)continue;
      for(const b of other){if(b.s<=a.s||b.n<2)continue;const d=a.p.distanceTo(b.p);if(d>.001&&d<.033){const push=(.033-d)*.13,delta=a.p.clone().sub(b.p).multiplyScalar(push/d);a.p.add(delta);b.p.sub(delta);}}
    }
  }
}
let frame=0;
function simulate(dt){
  frame++;
  const step=Math.min(dt, .034)*60;
  const breezeStrength=breeze?1:0;
  for(let s=0;s<strands.length;s++){
    const st=strands[s];
    st.pts[0].copy(guidePoint(st.lat,st.theta,0,st.length,st.layer));
    st.prev[0].copy(st.pts[0]);
    for(let n=1;n<st.active;n++){
      const p=st.pts[n],old=st.prev[n],velocity=p.clone().sub(old).multiplyScalar(.965);
      st.prev[n].copy(p);
      const t=n/(NODES-1),guide=guidePoint(st.lat,st.theta,t,st.length,st.layer);
      const wind=Math.sin(frame*.038+st.phase+t*4)*.0007*breezeStrength;
      p.add(velocity.multiplyScalar(step));
      p.y+=(-.0010*st.weight + Math.cos(st.phase+frame*.013)*.00012)*step*step;
      p.x+=(.00035+wind)*step*step;p.z+=Math.cos(st.phase+t*3)*.00011*step*step;
      p.add(guide.sub(p).multiplyScalar(.018*step));
      // Keep the fibers just outside the skull surface while allowing their tips to swing free.
      const hx=p.x/headRx,hy=(p.y-headCenterY)/headRy,hz=p.z/headRz;
      const radius=Math.sqrt(hx*hx+hy*hy+hz*hz);
      if(radius<1.015){const scale=1.015/Math.max(radius,.001);p.set(hx*scale*headRx,headCenterY+hy*scale*headRy,hz*scale*headRz);}
    }
    for(let pass=0;pass<2;pass++)for(let n=1;n<st.active;n++){
      const a=st.pts[n-1],b=st.pts[n],rest=guidePoint(st.lat,st.theta,n/(NODES-1),st.length,st.layer).distanceTo(guidePoint(st.lat,st.theta,(n-1)/(NODES-1),st.length,st.layer));
